      defaultConnection: 'സ്വന്തം ഓവർറൈഡ് ഇല്ലാത്ത ഓരോ പ്രൊഫൈലിനുമുള്ള സ്വതവേയുള്ള കണക്ഷൻ.',
      envOverrideTitle: 'എൻവയോൺമെന്റ് വേരിയബിളുകൾ ഈ ഡെസ്ക്ടോപ്പ് സെഷൻ നിയന്ത്രിക്കുന്നു.',
